import { CONFIG_INIT_SERVICES } from "../config_template.js";
import prompts from "prompts";
//#region src/utils/service_picker.ts
/**
* The picker's rows, in {@link CONFIG_INIT_SERVICES} order. Titles use the product names from
* the CLI's README ("Managed Better Auth", "Object Storage") rather than the `neon.ts` field
* names, since this is the list a user reads before they've seen a policy.
*/
const CHOICES = [
	{
		value: "auth",
		title: "Managed Better Auth",
		description: "Authentication with users and sessions stored in Postgres."
	},
	{
		value: "functions",
		title: "Functions",
		description: "Long-running, without timeouts, and closer to your database."
	},
	{
		value: "object-storage",
		title: "Object Storage",
		description: "S3-compatible blob storage that branches with your projects."
	},
	{
		value: "ai-gateway",
		title: "AI Gateway",
		description: "All models, one API, one bill. Powered by Databricks. Not available on the Neon free plan."
	}
];
/**
* Ask which services the scaffolded `neon.ts` should declare. Selecting nothing is a real
* answer — it yields the bare starter policy — so an empty list returns empty rather than
* re-prompting. Aborting (Ctrl-C) exits 1, matching the prompts in `link`.
*
* Callers guard the TTY themselves (see `initCmd`); this function assumes it may prompt.
*/
const pickServicesInteractively = async () => {
	const { services } = await prompts({
		onState: (state) => {
			if (state.aborted) {
				process.stdout.write("\x1B[?25h");
				process.stdout.write("\n");
				process.exit(1);
			}
		},
		type: "multiselect",
		name: "services",
		message: "Which Neon services should neon.ts declare? (space to toggle, enter to confirm)",
		instructions: false,
		choices: CHOICES.map((choice) => ({
			value: choice.value,
			title: choice.title,
			description: choice.description
		}))
	});
	if (!Array.isArray(services)) throw new Error("Aborted: no services selected.");
	return CONFIG_INIT_SERVICES.filter((service) => services.includes(service));
};
//#endregion
export { pickServicesInteractively };
